"""CX/rotation lowering with explicit phase compensation on clean workspace."""

import math
from dataclasses import replace

from examples.synthesis.tutorials.technology_demonstrations.classiq_paper.quantum_walk.classiq_discrete_quantum_walk.overview.exact_basis import (
    exact_rules,
)
from flagquantum import synth
from flagquantum.compiler.basis_conversion import convert_basis
from flagquantum.compiler.resource_estimation import estimate_resources
from flagquantum.core.ir import CircuitIR, Instruction


def rotation_basis(
    program: synth.Program, *, max_added_operations: int = 20_000
) -> CircuitIR:
    """Preserve the walk's clean-workspace isometry in CX/RZ/RY/RX.

    This is not an operator identity on dirty workspace. The acceptance tests
    prove the input-zero and output-zero contract for every logical column.
    U3(theta,phi,lambda) = exp(i*(phi+lambda)/2) RZ(phi) RY(theta) RZ(lambda).
    A final RZ(-2*phase) on a clean zero work qubit restores that phase.
    """
    logical = {wire for wires in program.registers.values() for wire in wires}
    hidden = tuple(
        wire
        for wire in range(estimate_resources(program.circuit).n_qubits)
        if wire not in logical
    )
    if not hidden:
        raise ValueError(
            "Rotation phase compensation requires a verified clean work qubit."
        )
    source = convert_basis(
        program.circuit,
        gates=("cx", "u3"),
        max_added_operations=max_added_operations,
        rules=exact_rules(),
    ).program
    operations: list[Instruction] = []
    phase = 0.0
    for instruction in source.instructions:
        if instruction.name == "cx":
            operations.append(instruction)
            continue
        angles = tuple(instruction.params[name] for name in ("theta", "phi", "lbd"))
        if any(
            isinstance(angle, bool)
            or not isinstance(angle, (float, int))
            or not math.isfinite(angle)
            for angle in angles
        ):
            raise ValueError(
                "This fixed-reference workflow requires finite real U3 angles."
            )
        theta, phi, lbd = angles
        phase += (phi + lbd) / 2
        for name, angle in (("rz", lbd), ("ry", theta), ("rz", phi)):
            operations.append(
                Instruction(
                    name,
                    instruction.wires,
                    params={"theta": angle},
                    metadata=instruction.metadata,
                )
            )
    operations.append(
        Instruction(
            "rz",
            (hidden[0],),
            params={"theta": -2 * phase},
            metadata={"phase_compensation": "input_zero_output_zero_workspace"},
        )
    )
    if len(operations) - len(program.circuit.instructions) > max_added_operations:
        raise ValueError("Rotation-basis expansion exceeds max_added_operations.")
    return replace(source, instructions=tuple(operations))

"""Operator-exact rules for a caller-requested CX/U3 named basis."""

import math
from collections.abc import Mapping

from flagquantum.compiler.basis_translation import (
    EQUIVALENCE_RULES,
    EquivalenceRule,
    with_equivalence_rule,
)
from flagquantum.core.ir import Instruction


def h_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """H equals U3(pi/2,0,pi), including its absolute phase."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": math.pi / 2, "phi": 0.0, "lbd": math.pi},
            metadata=instruction.metadata,
        ),
    )


def phase_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    """A phase gate equals U3(0,0,theta)."""
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": instruction.params["theta"]},
            metadata=instruction.metadata,
        ),
    )


def cphase_to_u3_cx(instruction: Instruction) -> tuple[Instruction, ...]:
    """Use three phase gates and two CX gates without a lost global phase."""
    control, target = instruction.wires
    half = instruction.params["theta"] * 0.5
    metadata = instruction.metadata
    return (
        Instruction(
            "u3",
            (control,),
            params={"theta": 0.0, "phi": 0.0, "lbd": half},
            metadata=metadata,
        ),
        Instruction(
            "u3",
            (target,),
            params={"theta": 0.0, "phi": 0.0, "lbd": half},
            metadata=metadata,
        ),
        Instruction("cx", (control, target), metadata=metadata),
        Instruction(
            "u3",
            (target,),
            params={"theta": 0.0, "phi": 0.0, "lbd": -half},
            metadata=metadata,
        ),
        Instruction("cx", (control, target), metadata=metadata),
    )


def x_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": math.pi, "phi": 0.0, "lbd": math.pi},
            metadata=instruction.metadata,
        ),
    )


def t_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": math.pi / 4},
            metadata=instruction.metadata,
        ),
    )


def tdg_to_u3(instruction: Instruction) -> tuple[Instruction, ...]:
    return (
        Instruction(
            "u3",
            instruction.wires,
            params={"theta": 0.0, "phi": 0.0, "lbd": -math.pi / 4},
            metadata=instruction.metadata,
        ),
    )


def exact_rules() -> Mapping[str, tuple[EquivalenceRule, ...]]:
    """Extend the immutable public rule table; leave all shared defaults untouched."""
    rules = EQUIVALENCE_RULES
    for opcode, builder in (
        ("h", h_to_u3),
        ("phase", phase_to_u3),
        ("cphase", cphase_to_u3_cx),
        ("x", x_to_u3),
        ("t", t_to_u3),
        ("tdg", tdg_to_u3),
    ):
        rules = with_equivalence_rule(rules, opcode, builder)
    return rules

"""Native translations of the commented quantum-walk references."""

from typing import Annotated

from flagquantum import synth
from flagquantum.synth import (
    H,
    Output,
    QArray,
    QBit,
    QNum,
    X,
    adjoint,
    allocate,
    control,
    qfunc,
)


@qfunc
def increment(x: QNum) -> None:
    x += 1


@qfunc
def decrement(x: QNum) -> None:
    x -= 1


@qfunc
def qiskit_tket_walk(x: Output[Annotated[QNum, 6]], coin: Output[QBit]) -> None:
    allocate(x)
    allocate(coin)
    H(coin)
    control(coin == 1, lambda: increment(x))
    control(coin == 0, lambda: decrement(x))


@qfunc
def catalyst_cascade_step(index: int, x: QArray[QBit]) -> None:
    control(x[0:index], lambda: X(x[index]))
    X(x[0])


@qfunc
def catalyst_commented_shift(x: QArray[QBit]) -> None:
    for index in range(5, 0, -1):
        catalyst_cascade_step(index, x)


@qfunc
def catalyst_inverse_shift(x: QArray[QBit]) -> None:
    with adjoint():
        catalyst_commented_shift(x)


@qfunc
def catalyst_commented_walk(x: Output[QArray[QBit]], coin: Output[QBit]) -> None:
    allocate(6, x)
    allocate(coin)
    H(coin)
    control(coin == 1, lambda: catalyst_commented_shift(x))
    control(coin == 0, lambda: catalyst_inverse_shift(x))


def build_program(*, catalyst: bool = False) -> synth.Program:
    entry = catalyst_commented_walk if catalyst else qiskit_tket_walk
    return synth.synthesize(entry, max_qubits=16, max_workspace=9, max_operations=20000)

"""Independent dense permutation oracle for seven logical reference-walk bits."""

import torch

import flagquantum as fq


def permutation(*, catalyst: bool) -> tuple[int, ...]:
    """Derive the source Boolean cascade without quantum synthesis or QFT."""
    if not catalyst:
        return tuple((word + 1) % 64 for word in range(64))
    image: list[int] = []
    for word in range(64):
        bits = [(word >> index) & 1 for index in range(6)]
        for index in range(5, 0, -1):
            bits[index] ^= int(all(bits[:index]))
            bits[0] ^= 1
        image.append(sum(bit << index for index, bit in enumerate(bits)))
    if sorted(image) != list(range(64)):
        raise ValueError("Source shift is not reversible.")
    return tuple(image)


def reference_circuit(*, catalyst: bool = False) -> fq.Circuit:
    """Build H then an independent 128-column controlled permutation.

    The 128x128 complex128 matrix occupies 256 KiB and is used for correctness
    only. It is not the native lowering or a resource/performance baseline.
    """
    image = permutation(catalyst=catalyst)
    inverse = tuple(image.index(word) for word in range(64))
    matrix = torch.zeros((128, 128), dtype=torch.complex128)
    for word in range(64):
        matrix[2 * inverse[word], 2 * word] = 1
        matrix[2 * image[word] + 1, 2 * word + 1] = 1
    return fq.Circuit(7, dtype=torch.complex128).h(6).any(*range(7), matrix=matrix)
